    "936 — 937 · 石敬瑭建後晉：割燕雲十六州予契丹，江淮尚為楊吳": "936–937 · Shi Jingtang Cedes Sixteen Prefectures to Khitan and Founds Later Jin; Yang Wu in Jianghuai",
    "937 — 945 · 李昪代吳建南唐：北方後晉與契丹並立，南方南唐、閩、吳越爭衡": "937–945 · Li Bian Founds Southern Tang; Later Jin, Khitan, Min & Wuyue",
    "958 — 959 · 周世宗平淮南：南唐獻江北淮南十四州，後周與南唐以長江為界": "958–959 · Emperor Shizong Conquers Huainan: Southern Tang Cedes 14 Prefectures North of the Yangtze",
    "959 — 960 · 周世宗北伐幽燕：收復瀛、莫、易三州與瓦橋三關": "959–960 · Emperor Shizong's Northern Expedition: Recovery of Ying, Mo & Yi Prefectures and Three Passes",
    "763 — 764 · 安史之亂平定：史朝義敗亡，降將田承嗣、李懷仙、李寶臣分領魏博、幽州、成德，藩鎮割據肇端": "763–764 · Rebellion Ends: Shi Chaoyi falls; surrendered generals Tian Chengsi, Li Huaixian and Li Baochen keep Weibo, Youzhou and Chengde, opening the age of regional warlords",
    "764 — 790 · 吐蕃陷河隴與孤懸西域：涼州失守河西走廊被截斷，安西、北庭孤懸絕域堅守": "764–790 · Fall of Hexi & Isolated Protectorates: Tubo captures Liangzhou and severs the Hexi Corridor; Anxi and Beiting hold out in isolation",
    "1644 — 1661 · 清軍入關與南明抗清：清廷定都北京經略中原，南明據南方抗清，臺灣尚為荷佔": "1644–1661 · Qing Entry & Southern Ming Resistance: Qing establishes rule from Beijing while Southern Ming resists in the south and Taiwan remains Dutch-ruled",
    "1661 — 1681 · 鄭成功收復臺灣與三藩之亂：明鄭驅逐荷蘭殖民者設承天府，吳三桂等三藩於南方舉兵": "1661–1681 · Koxinga Recovers Taiwan & Revolt of the Three Feudatories: Kingdom of Tungning established in Taiwan; Three Feudatories rebel in the south",
