    "前 403 — 前 341 · 三家分晉、田氏代齊與魏霸中原：七雄並立，巴蜀、越、中山尚存": "403–341 BCE · Partition of Jin, Tian Qi & Hegemony of Wei: Seven Warring States alongside Ba-Shu, Yue & Zhongshan",
    "前 230 — 前 229 · 秦王掃六合之首滅韓國：內史騰俘韓王安，置潁川郡": "230–229 BCE · Unification Wars — Fall of Han: Governor Teng Captures King An and Establishes Yingchuan Commandery",
    "前 228 — 前 227 · 秦王掃六合之攻克邯鄲滅趙：王翦破趙俘趙王遷，公子嘉北奔代郡": "228–227 BCE · Unification Wars — Fall of Zhao: Wang Jian Captures Handan; Prince Jia Flees to Dai",
    "前 226 · 秦王掃六合之易水破燕：荊軻刺秦后王翦攻拔燕都薊城，燕王喜東退遼東": "226 BCE · Unification Wars — Capture of Jicheng: Wang Jian Takes the Yan Capital; King Xi Retreats to Liaodong",
    "前 225 — 前 224 · 秦王掃六合之水灌大梁滅魏：王賁引河溝灌城，魏王假出降，三晉盡入秦": "225–224 BCE · Unification Wars — Fall of Wei: Wang Ben Floods Daliang and Receives King Jia’s Surrender",
    "前 223 — 前 222 · 秦王掃六合之王翦六十萬滅楚、王賁滅燕代：六國唯餘齊國孤懸東海": "223–222 BCE · Unification Wars — Fall of Chu, Yan & Dai: Wang Jian Conquers Chu and Wang Ben Takes Liaodong; Only Qi Remains",
    "戰國初期（約前350年 · 三家分晉與七雄並立）": "Early Warring States (c. 350 BCE · Partition of Jin & Seven Powers)",
    "前403年周威烈王冊命韓、趙、魏為諸侯（《資治通鑑》開篇），前386年田氏代齊，戰國七雄格局確立；魏文侯、武侯任李悝、吳起率先稱雄中原，巴、蜀、越、中山與東周王畿並存。": "In 403 BCE King Weilie of Zhou recognized Han, Zhao, and Wei as feudal lords (opening Zizhi Tongjian), and in 386 BCE the Tian house became Marquis of Qi. Wei initially dominated the Central Plains while Ba, Shu, Yue, Zhongshan, and Royal Zhou coexisted.",
    "戰國後期（前260年 · 白起拔郢與長平之戰）": "Late Warring States (260 BCE · Capture of Ying & Battle of Changping)",
    "前284年樂毅率五國聯軍破齊；前278年秦將白起拔楚都郢置南郡，楚東遷陳郢；前260年秦趙長平決戰，白起坑趙卒四十萬，山東六國再難獨力抗秦。": "In 284 BCE Yue Yi led a five-state coalition to rout Qi; in 278 BCE Bai Qi captured the Chu capital Ying, forcing Chu east to Chen; in 260 BCE Bai Qi destroyed 400,000 Zhao troops at Changping, leaving no eastern state able to match Qin alone.",
    "秦王政親政前夕（前238年 · 滅周置三川、東郡與六國合縱終結）": "Eve of Unification (238 BCE · King Zheng Assumes Personal Rule)",
    "秦王掃六合 · 首滅韓國（前230年 · 內史騰俘韓王安，置潁川郡）": "Qin Unification · Conquest of Han (230 BCE · Yingchuan Commandery Established)",
    "前230年（秦王政十七年），秦內史騰攻韓，俘韓王安，盡納其地置潁川郡。韓國成為六國中第一個覆滅的諸侯國。": "In 230 BCE Qin Governor Teng captured King An of Han at Xinzheng and established Yingchuan Commandery, making Han the first of the six states to fall.",
    "秦王掃六合 · 攻克邯鄲滅趙（前228年 · 王翦破趙，公子嘉奔代）": "Qin Unification · Fall of Handan & Conquest of Zhao (228 BCE)",
    "前228年（秦王政十九年），王翦大破趙軍攻克邯鄲，俘趙王遷；趙公子嘉率宗族奔代稱代王，與燕聯兵拒秦。": "In 228 BCE Wang Jian captured Handan and King Qian of Zhao; Prince Jia fled north to Dai to continue resistance alongside Yan.",
    "秦王掃六合 · 易水破燕拔薊城（前226年 · 燕王喜東保遼東）": "Qin Unification · Capture of Jicheng in Yan (226 BCE)",
    "前227年荊軻刺秦不果，王翦、辛勝大破燕代聯軍於易水之西，前226年十月攻拔燕都薊城，燕王喜斬太子丹首級獻秦，退保遼東襄平。": "Following Jing Ke’s failed assassination attempt (227 BCE), Wang Jian routed the Yan-Dai army west of the Yi River and captured Jicheng in 226 BCE, forcing King Xi of Yan to retreat to Liaodong.",
    "秦王掃六合 · 水灌大梁滅魏（前225年 · 三晉盡入於秦）": "Qin Unification · Flooding of Daliang & Conquest of Wei (225 BCE)",
    "前225年（秦王政二十二年），王賁引黃河、鴻溝之水灌魏都大梁，三月城壞，魏王假出降，魏國滅亡，三晉故地盡歸於秦。": "In 225 BCE Wang Ben diverted the Yellow River and Honggou Canal to flood Daliang for three months; King Jia surrendered, completing Qin’s conquest of the Three Jins.",
    "秦王掃六合 · 滅楚平燕代，唯餘齊國（前223—前222年）": "Qin Unification · Conquest of Chu, Yan & Dai; Only Qi Remains (223–222 BCE)",
    "前223年王翦、蒙武統六十萬大軍破楚拔壽春，俘楚王負芻；前222年王賁攻滅遼東燕王喜與代王嘉，王翦悉定江南置會稽郡，六國唯餘東海之濱的齊國孤懸。": "In 223 BCE Wang Jian and Meng Wu conquered Chu at Shouchun; in 222 BCE Wang Ben extinguished Yan in Liaodong and Dai while Wang Jian pacified Jiangnan, leaving Qi isolated on the eastern coast.",
