    "189—195 年 · 董卓入京與關東諸侯並起": "189–195 CE · Dong Zhuo in the Capital & Rise of the Guandong Coalition",
    "196—199 年 · 曹操迎獻帝遷許與袁紹南北爭衡": "196–199 CE · Cao Cao Escorts Emperor Xian to Xuchang vs. Yuan Shao in Hebei",
    "200—207 年 · 官渡之戰與曹操統一北方": "200–207 CE · Battle of Guandu & Cao Cao Unifying the North",
    "200 年曹操於官渡之戰以少勝多擊敗袁紹主力，隨後平定冀、青、幽、並四州及烏桓，基本統一北方；南方劉表據荊州、劉璋據益州、孫權嗣位統事江東。": "In 200 Cao Cao defeated Yuan Shao against the odds at the Battle of Guandu and went on to pacify Jizhou, Qingzhou, Youzhou, Bingzhou, and the Wuhuan, unifying northern China while Liu Biao held Jingzhou, Liu Zhang held Yizhou, and Sun Quan consolidated Jiangdong.",
    "208—213 年 · 赤壁之戰：孫劉破曹與劉備據荊州": "208–213 CE · Battle of Red Cliffs: Sun–Liu Alliance & Liu Bei in Jingzhou",
    "208 年曹操南下荊州，孫權、劉備聯軍於赤壁大破曹軍；戰後劉備收江南荊州四郡並向孫權“借荊州”（南郡），據有荊州，此時巴蜀益州仍由劉璋割據，直至 214 年劉備入成都。": "In 208 the allied forces of Sun Quan and Liu Bei defeated Cao Cao at the Battle of Red Cliffs; Liu Bei secured southern Jingzhou and Nanjun to hold Jingzhou, while Yizhou (Sichuan) remained under Liu Zhang until 214.",
    "214—218 年 · 劉備入成都，跨有荊、益二州": "214–218 CE · Liu Bei Takes Chengdu, Spanning Jingzhou and Yizhou",
    "214 年劉備率軍入成都迫降劉璋，正式領益州牧，實踐《隆中對》“跨有荊、益”戰略，與北方曹操、江東孫權形成三方鼎立之勢。": "In 214 Liu Bei entered Chengdu and received Liu Zhang's surrender to become Governor of Yizhou, fulfilling the Longzhong Plan by holding both Jingzhou and Yizhou opposite Cao Cao in the north and Sun Quan in Jiangdong.",
