    "189 年董卓入洛陽廢立少帝，190 年袁紹、曹操等關東諸侯聯兵討董，董卓挾獻帝西遷長安；192 年董卓誅後李傕、郭汜把持長安朝政，北方袁紹據冀州與幽州公孫瓚爭河北，涼州馬騰韓遂割據，曹操崛起兗豫，南方劉表據荊州、劉焉據益州、孫堅等起兵江東。": "In 189 Dong Zhuo seized Luoyang and deposed the young emperor; in 190 the Guandong coalition rose against him and Dong Zhuo moved Emperor Xian west to Chang'an. In the north Yuan Shao in Jizhou contested Hebei against Gongsun Zan in Youzhou, Ma Teng and Han Sui held Liangzhou, Cao Cao rose in Yanzhou and Yuzhou, Liu Biao held Jingzhou, Liu Yan held Yizhou, and Sun Jian rose in Jiangdong.",
    "196 年漢獻帝東歸洛陽，曹操迎天子遷都許昌，“奉天子以令不臣”，據有河南、兗、豫、徐州；北方袁紹滅公孫瓚盡統冀、青、幽、並四州，與曹操隔黃河對峙；涼州及關西由馬騰、韓遂等割據，江東孫策渡江平定吳會六郡。": "In 196 Cao Cao escorted Emperor Xian to Xuchang, holding Henan, Yanzhou, Yuzhou, and Xuzhou in the imperial name; north of the Yellow River, Yuan Shao eliminated Gongsun Zan to unite the four provinces of Jizhou, Qingzhou, Youzhou, and Bingzhou; Ma Teng and Han Sui held Liangzhou and Guanxi, while Sun Ce conquered Jiangdong.",
