    "北魏六鎮之一，宇文泰、獨孤信、楊忠（隋）、李虎（唐）皆出於此，關隴集團搖籃": "One of the Six Frontier Towns of Northern Wei; cradle of Yuwen Tai, the Guanlong Group, and the Sui and Tang imperial houses",
