    "553 — 554 · 西魏尉遲迥平蜀：巴蜀漢中併入西魏，梁元帝蕭繹都江陵": "553–554 · Western Wei Conquers Sichuan; Emperor Yuan of Liang Rules from Jiangling",
    "554 — 557 · 西魏於謹克江陵立蕭詧為西梁主，北齊南拓江淮": "554–557 · Western Wei Captures Jiangling & Installs Western Liang; Northern Qi Takes Jianghuai",
    "581 — 587 · 隋初南北對峙：楊堅代周建隋，江陵西梁存續，與江南陳朝隔江並立": "581–587 · Founding of Sui, Western Liang at Jiangling, and Southern Chen",
    "587 — 589 · 隋文帝廢西梁併入隋境，大軍臨江蓄勢滅陳": "587–589 · Emperor Wen of Sui Abolishes Western Liang and Prepares to Conquer Chen",
    "西梁都城（587 年隋廢西梁置荊州總管府）": "Capital of Western Liang (abolished by Sui in 587)",
    "前 340 — 前 317 · 商鞅收河西、魏遷大梁與五國相王：巴蜀、越、中山、義渠尚存": "340–317 BCE · Shang Yang Retakes Hexi, Wei Moves to Daliang & Five-State Royal Accord: Ba–Shu, Yue, Zhongshan & Yiqu Remain",
    "戰國中期之初（前340 — 前317 · 商鞅收河西與五國相王）": "Early Mid-Warring States (340–317 BCE · Qin Retakes Hexi & Five-State Royal Accord)",
    "前340年商鞅破魏收復河西，魏惠王東遷大梁並獻上郡於秦；前323年公孫衍發起“五國相王”。此時巴、蜀、越、中山與義渠諸國皆尚獨立存續。": "In 340 BCE Shang Yang defeated Wei to retake Hexi, forcing King Hui of Wei to move his capital east to Daliang and cede Shangjun to Qin; in 323 BCE Gongsun Yan initiated the Five-State Royal Accord. Ba, Shu, Yue, Zhongshan, and Yiqu all remained independent.",
    "前 316 — 前 307 · 秦司馬錯滅巴蜀、丹陽之戰取漢中：越、中山、義渠尚存": "316–307 BCE · Sima Cuo Conquers Ba–Shu & Qin Takes Hanzhong at Danyang: Yue, Zhongshan & Yiqu Remain",
    "戰國中期前葉（前316 — 前307 · 秦滅巴蜀與丹陽之戰取漢中）": "Mid-Warring States (316–307 BCE · Qin Conquest of Ba–Shu & Hanzhong)",
    "前316年秦惠文王遣司馬錯滅巴、蜀置巴郡與蜀郡，前312年丹陽、藍田之戰大破楚軍取漢中郡；此時江南越國、河北中山國及隴東義渠尚存。": "In 316 BCE King Huiwen of Qin sent Sima Cuo to conquer Ba and Shu, and in 312 BCE Qin defeated Chu at Danyang to take Hanzhong Commandery; Yue in the southeast, Zhongshan in Hebei, and Yiqu in the northwest still remained.",
    "前 306 — 前 301 · 楚懷王滅越盡取舊吳之地：中山、義渠尚存，燕尚未東闢遼東": "306–301 BCE · Chu Annexes Yue Across Former Wu Lands: Zhongshan & Yiqu Remain (Pre-Liaodong Expansion)",
    "戰國中期（前306 — 前301 · 楚懷王滅越與胡服騎射）": "Mid-Warring States (306–301 BCE · Chu Annexation of Yue & Zhao Cavalry Reforms)",
    "前306年楚懷王乘越國內亂攻滅越國，盡取舊吳之地並置江東；北方趙武靈王推行胡服騎射，中山與義渠尚存，燕國尚未東闢遼東。": "In 306 BCE King Huai of Chu conquered Yue and absorbed the former Wu-Yue lands; in the north King Wuling of Zhao pursued cavalry archery reforms while Zhongshan and Yiqu persisted and Yan had not yet expanded into Liaodong.",
    "前 296 — 前 279 · 趙惠文王滅中山、五國伐秦與樂毅破齊：楚保郢都、義渠尚存": "296–279 BCE · Zhao Conquers Zhongshan & Yue Yi Routs Qi: Chu Holds Yingdu & Yiqu Remains",
    "戰國中後期（前296 — 前279 · 趙滅中山與樂毅破齊）": "Late Mid-Warring States (296–279 BCE · Zhao Conquest of Zhongshan & Yue Yi’s Campaign Against Qi)",
    "前296年趙惠文王徹底攻滅中山國，北境連成一片；前284年燕昭王拜樂毅統五國聯軍大破齊軍。此時白起尚未拔郢，楚都仍在江陵郢都，隴東義渠尚存。": "In 296 BCE King Huiwen of Zhao extinguished Zhongshan, uniting northern Hebei; in 284 BCE Yue Yi led a five-state coalition to rout Qi. Prior to Bai Qi’s 278 BCE campaign, the Chu capital remained at Ying (Jiangling) and Yiqu still stood in Longdong.",
