    "南平·三明": "Nanping / Sanming",
    "開元二十四年（736年）置汀州，與福、建、泉、漳合稱唐代福建五州": "Established as Tingzhou in 736 CE, forming the five Tang prefectures of Fujian together with Fuzhou, Jianzhou, Quanzhou, and Zhangzhou",
    "武德四年（621年）置建州，與福州合稱“福建”，為福建得名之源": "Established as Jianzhou in 621 CE; combined with Fuzhou to coin the name \"Fujian\"",
    "景雲二年（711年）改武榮州為泉州，唐代四大外貿海港之一": "Renamed Quanzhou in 711 CE; one of the four great maritime trade ports of Tang China",
    "垂拱二年（686年）陳元光請置漳州，開漳聖王經營閩南之始": "Established as Zhangzhou in 686 CE by Chen Yuanguang, marking the development of southern Fujian",
    "元改南劍路為延平路，控扼閩江上游三溪匯流要衝": "Renamed Yanping Route under the Yuan, commanding the upper Min River confluence",
    "福建八府之一，轄南平、沙縣、尤溪、永安、將樂等縣，正統年間鄧茂七起義於此": "One of the Eight Prefectures of Fujian governing Nanping, Shaxian, Youxi, and Yong'an; site of the 1448 Deng Maoqi rebellion",
    "福建省八府之一，連線閩北延建與閩西汀州之水陸咽喉，領南平、沙縣、永安等縣": "One of the Eight Prefectures of Fujian linking northern and western Fujian across Nanping, Shaxian, and Yong'an",
