    "滎陽 · 千乘": "Xingyang · Qiancheng",
    "1371 年湯和、傅友德水陸並進滅四川明夏，巴蜀併入明廷並設烏斯藏都司；北方北元與遼東納哈出尚存，西南雲南仍由元梁王把匝剌瓦爾密割據。": "In 1371 Tang He and Fu Youde conquered Ming Xia in Sichuan and established the Ü-Tsang Commission, while Northern Yuan and Naghachu held the north and Liaodong, and the Yuan Prince of Liang still held Yunnan.",
    "前256—前249年秦滅兩週置三川郡，前247年置太原郡，前242年置東郡與齊接界，徹底腰斬六國南北合縱通道；前238年秦王政親政，部署十年滅六國之戰。": "Qin annexed the Eastern Zhou domain (256–249 BCE), established Taiyuan (247 BCE) and Dongjun (242 BCE) to sever the north-south coalition corridor, and in 238 BCE King Zheng assumed personal rule to launch the unification campaigns.",
    "前 300 — 前 297 · 燕將秦開卻東胡闢燕北五郡、趙武靈王闢雲中雁門": "300–297 BCE · Yan General Qin Kai Opens Five Northern Frontier Commanderies; King Wuling of Zhao Opens Yunzhong & Yanmen",
    "戰國中期後葉（前300 — 前297 · 燕將秦開闢燕北五郡與趙略中山）": "Late Mid-Warring States (300–297 BCE · Yan General Qin Kai Expands into Liaodong)",
    "前300年燕將秦開大破東胡卻地千里，筑北長城置上谷、漁陽、右北平、遼西、燕北五郡；趙武靈王闢雲中、雁門，中山國僅餘靈壽一隅。": "In 300 BCE Yan general Qin Kai pushed back the Donghu by a thousand li and established five northern commanderies into Liaodong; King Wuling of Zhao established Yunzhong and Yanmen while Zhongshan held onto Lingshou.",
    "魯": "Lu",
    "薛郡": "Xue Jun",
    "原魯國都城，前249年楚考烈王滅魯併入楚境": "Former capital of Lu, annexed into Chu by King Kaolie in 249 BCE",
    "秦置薛郡轄魯縣（曲阜），孔子故里；楚漢之際項羽曾封魯公": "Administered under Qin Xue Commandery as Lu County (Qufu), birthplace of Confucius; former title fief of Xiang Yu as Duke of Lu",
    "戰國晚期（前249年 · 楚考烈王滅魯與秦滅兩週置三川郡）": "Late Warring States (249 BCE · Chu Annexes Lu & Qin Establishes Sanchuan Commandery)",
    "前256—前249年秦滅西周國與東周公國置三川郡；前249年楚考烈王伐魯滅之、遷魯頃公於莒，春申君黃歇徙封蘭陵，禮樂宗邦魯國併入楚境。": "Between 256 and 249 BCE Qin extinguished Western and Eastern Zhou to establish Sanchuan Commandery; in 249 BCE King Kaolie of Chu annexed the ancient ritual state of Lu at Qufu, relocating Duke Qing to Ju while Lord Chunshen took Lanling as his fief.",
    "前 278 — 前 250 · 白起拔郢、秦滅義渠與長平之戰：秦取南郡上黨北地，魯周尚存": "278–250 BCE · Fall of Ying, Conquest of Yiqu & Battle of Changping: Qin Dominates the West while Lu and Zhou Survive",
    "前 249 — 前 239 · 楚考烈王滅魯與秦滅兩週：魯國併入楚境，秦置三川郡": "249–239 BCE · Chu Annexes Lu & Qin Extinguishes Zhou: State of Lu Merged into Chu; Qin Establishes Sanchuan",
    "前 238 — 前 231 · 秦王政親政與滅六國前夕：秦增置太原、東郡，腰斬六國合縱": "238–231 BCE · King Zheng Assumes Personal Rule: Qin Adds Taiyuan & Dongjun, Bisecting the Six States",
    "燕將秦開大破東胡卻地千里，筑北長城置燕北五郡": "Yan general Qin Kai routs the Donghu, builds the northern Great Wall, and establishes the Five Northern Frontier Commanderies",
    "秦滅西周國遷九鼎；蜀守李冰修築都江堰": "Qin extinguishes Western Zhou and seizes the Nine Tripods; Governor Li Bing builds Dujiangyan",
    "都江堰 · 王城（洛陽）": "Dujiangyan · Wangcheng (Luoyang)",
    "楚考烈王伐滅魯國遷魯頃公於莒；秦呂不韋滅東周置三川郡": "King Kaolie of Chu annexes the State of Lu; Qin Chancellor Lü Buwei extinguishes Eastern Zhou and establishes Sanchuan Commandery",
    "曲阜 · 洛陽": "Qufu · Luoyang",
    "關中及雍州治所重鎮，永嘉之亂後晉愍帝即位於此": "Seat of Yong Province in Guanzhong where Emperor Min reigned as the last Western Jin ruler (313–316 CE)",
    "遼聖宗營建中京大定府；宋遼沿邊廣設榷場互市": "Emperor Shengzong of Liao builds the Central Capital Dading Fu as Song-Liao border trade markets flourish",
    "慶曆五年滕子京重修岳陽樓，六年范仲淹作《岳陽樓記》": "Teng Zijing rebuilt Yueyang Tower in 1045 CE; Fan Zhongyan composed Memorial to Yueyang Tower in 1046 CE",
    "慶曆五年歐陽修貶知滁州，六年作《醉翁亭記》": "Ouyang Xiu arrived in exile at Chu Zhou in 1045 CE and composed Pavilion of the Old Drunkard in 1046 CE",
    "大中祥符元年宋真宗幸曲阜謁孔廟，五年改仙源縣": "Emperor Zhenzong visited the Temple of Confucius at Qufu in 1008 CE and renamed the county Xianyuan in 1012 CE",
    "太平興國四年置太平軍、五年改興化軍，木蘭陂水利與媽祖故里": "Established in 979 CE and named Xinghua Military Prefecture in 980 CE, famed for Mulan Weir and Mazu heritage",
    "金代山東東路海防名州，王重陽於昆嵛山、寧海創全真道收北七真": "Jin coastal prefecture where Wang Chongyang founded Quanzhen Taoism around Mt. Kunyu and Ninghai, teaching the Seven True Ones",
    "宋改昌化軍為南寧軍，元屬海北海南道": "Renamed Nanning Military Prefecture under Song and administered under the Haibei–Hainan Circuit in Yuan",
    "中書省直轄泰安州（至元五年析東平路隸省部）": "Tai'an Zhou directly under the Central Secretariat (detached from Dongping Route in 1268 CE)",
    "明代漕運總督與總理河道駐地，九省通衢": "Seat of the Ming Viceroy of Grain Transport and Director-General of the Grand Canal",
    "福建八府之一，成化十四年析置永定縣，正德間王陽明巡撫南贛汀漳平定漳寇，閩西土樓肇興": "One of the Eight Prefectures of Fujian; Yongding County was carved out in 1478 CE, Wang Yangming pacified border bandits in 1517 CE, and Hakka tulou flourished",
    "控扼漢江上游川陝鄂交界咽喉，設鄖陽總兵鎮守": "Commanded the strategic upper Han River borderland at the junction of Sichuan, Shaanxi, and Hubei",
